# Work orders v2 + daily routine: ticks survive the background redraw; transfer many → one; a new feed sheet with an
# amount per tank; grading, harvest, cleaning (sections), a visit shown ahead; per-site delivery; routine ticked by workers.
import os; os.environ['E2E_PORT'] = '8879'
import harness
harness.DEFAULT_UNITS[:] = [(f'F1.S01T{t:02d}', 500, 100) for t in range(1, 5)] + [(f'F3.S{s:02d}T01', 300, 5) for s in range(1, 5)] + [('F3.S05T01', 0, 0)]
from harness import *
with sync_playwright() as p:
    BROWSER = p.chromium.launch(); harness_browser[0] = BROWSER
    sb = MockSB(); sb.add_user('eng@example.com', 'eng123', role='engineer')
    sb.add_user('sajed@workers.dar-aqua.app', 'work123', role='worker', perms=['input_feeding', 'input_mortality', 'input_harvest', 'farm:F3'])
    sb.add_user('irfan@workers.dar-aqua.app', 'work123', role='worker', perms=['input_feeding', 'input_mortality', 'farm:F1'])
    c1, pe = new_page(p, sb); login(pe, 'eng@example.com', 'eng123'); pe.wait_for_function('() => !!window._cloudSyncDone', timeout=10000)
    pe.on('dialog', lambda d: d.accept())
    chip = lambda lst, u: f'.wo-chip[data-list="{lst}"][data-v="{u}"]'
    check('W1 engineers have "📋 أوامر الشغل" (3 tabs: new / orders / routine)', pe.evaluate("canAccessView('work-orders')"))
    pe.evaluate("window._wo={farm:'F3'}; show('work-orders')"); pe.wait_for_timeout(300)
    pe.click('.wo-kind[data-k="transfer"]'); pe.wait_for_timeout(200)
    for u in ['F3.S01T01', 'F3.S02T01']: pe.click(chip('from', u))
    pe.click(chip('to', 'F3.S05T01'))
    pe.evaluate("daBgRefresh('work-orders')"); pe.wait_for_timeout(200)
    check('W2 the ticks survive the background redraw (the bug)', pe.evaluate("daWoState().from.join(',')") == 'F3.S01T01,F3.S02T01' and pe.evaluate(f"getComputedStyle(document.querySelector('{chip('from','F3.S01T01')}')).color") == 'rgb(255, 255, 255)')
    check('W3 transfer: an empty tank can be the destination', pe.evaluate("daWoState().to[0]") == 'F3.S05T01')
    pe.click('#wo-save'); pe.wait_for_timeout(300)
    pe.click('.wo-kind[data-k="nofeed"]'); pe.wait_for_timeout(150)
    for u in ['F3.S03T01', 'F3.S04T01']: pe.click(chip('from', u))
    pe.fill('#wo-text', 'هننقلهم بكره'); pe.click('#wo-save'); pe.wait_for_timeout(300)
    pe.click('.wo-kind[data-k="feed"]'); pe.wait_for_timeout(150)
    pe.click(chip('from', 'F3.S01T01')); pe.wait_for_timeout(150); pe.click(chip('from', 'F3.S02T01')); pe.wait_for_timeout(150)
    pe.fill('.wo-kg[data-u="F3.S01T01"]', '1.2'); pe.fill('.wo-kg[data-u="F3.S02T01"]', '0.8'); pe.click('#wo-save'); pe.wait_for_timeout(300)
    pe.click('.wo-kind[data-k="harvest"]'); pe.wait_for_timeout(150); pe.click(chip('from', 'F3.S04T01')); pe.click('#wo-save'); pe.wait_for_timeout(300)
    pe.click('.wo-kind[data-k="clean"]'); pe.wait_for_timeout(150); pe.click(chip('secs', 'F3.S01')); pe.click(chip('secs', 'F3.S03')); pe.click('#wo-save'); pe.wait_for_timeout(300)
    pe.click('.wo-kind[data-k="visit"]'); pe.wait_for_timeout(150); pe.evaluate("daWoSet('date', daAddDays(daToday(),3), true)"); pe.wait_for_timeout(150); pe.fill('#wo-text', 'زيارة من الوزارة'); pe.click('#wo-save'); pe.wait_for_timeout(300)
    A = pe.evaluate("daWoAll().map(o=>[o.kind,o.tanks.join('+'),(o.to||[]).join('+'),JSON.stringify(o.kgs||{}),(o.secs||[]).join('+')])")
    check('W4 transfer many → one, don\'t feed 2 tanks, feed sheet per tank, harvest, cleaning of 2 sections, a visit', [a[0] for a in A] == ['transfer', 'nofeed', 'feed', 'harvest', 'clean', 'visit'] and A[0][1:3] == ['F3.S01T01+F3.S02T01', 'F3.S05T01'] and A[2][3] == '{"F3.S01T01":1.2,"F3.S02T01":0.8}' and A[4][4] == 'F3.S01+F3.S03', A)
    # the routine for F3
    pe.evaluate("daWoSet('tab','routine',true)"); pe.wait_for_timeout(200)
    pe.click('#rt-add'); pe.wait_for_timeout(100); pe.fill('.rt-time >> nth=0', '00:00'); pe.fill('.rt-text >> nth=0', 'قياس أكسجين كل السكاشن')
    pe.click('#rt-add'); pe.wait_for_timeout(100); pe.fill('.rt-time >> nth=1', '00:01'); pe.fill('.rt-text >> nth=1', 'شيل النافق'); pe.click('#rt-save'); pe.wait_for_timeout(300)
    check('W5 the daily routine per site is saved (synced)', pe.evaluate("(daRoutine().F3||[]).length") == 2 and pe.evaluate("daIsSyncedKey(DA_ROUTINE_KEY)"))
    c2, ps = new_page(p, sb); ps.set_viewport_size({'width': 390, 'height': 844}); login(ps, 'sajed@workers.dar-aqua.app', 'work123'); ps.wait_for_function('() => !!window._cloudSyncDone', timeout=10000); ps.wait_for_timeout(600); ps.evaluate('daTabRefresh()'); ps.wait_for_timeout(1500)
    check('W6 Sajed (F3) sees 6 orders + 2 routine items in the bell — not F1\'s', ps.evaluate("document.getElementById('wo-bell').textContent") == '🔔 8', ps.evaluate("document.getElementById('wo-bell').textContent"))
    ps.evaluate("window._fs={farm:'F3'}; show('feed-sheet',true)"); ps.wait_for_timeout(400)
    v = lambda u: ps.evaluate(f"(r => document.getElementById('fs-'+r.i+'-m0').value)(window._fs.rows.find(r=>r.unit==='{u}'))")
    check('W7 don\'t feed (2 tanks) = X; the new feed sheet fills each tank\'s own amount', v('F3.S03T01') == 'X' and v('F3.S04T01') == 'X' and v('F3.S01T01') == '1.2' and v('F3.S02T01') == '0.8')
    ps.evaluate("show('wo-mine',true)"); ps.wait_for_timeout(300); txt = ps.inner_text('#content')
    check('W8 the worker\'s page: today\'s orders, the visit ahead ("take care, clean well"), today\'s routine', 'زيارة' in txt and 'نضّفوا المكان' in txt and 'روتين النهارده' in txt and 'شيل النافق' in txt, txt[:300])
    ps.click('.rt-ok >> nth=0'); ps.wait_for_timeout(400)
    check('W9 a routine item ticked (who did it shown)', ps.evaluate("Object.keys(daRoutineDone('F3', daToday())).length") == 1 and '✔' in ps.inner_text('.rt-card'))
    ps.evaluate("addTX({id:'t1',type:'transfer_out',date:daToday(),unit:'F3.S01T01',fishNo:10,avgWt:5,txGroup:'g',_skipValidation:true}); addTX({id:'t2',type:'transfer_out',date:daToday(),unit:'F3.S02T01',fishNo:10,avgWt:5,txGroup:'g',_skipValidation:true})"); ps.wait_for_timeout(300)
    check('W10 the transfer of BOTH tanks recorded → the order closes by itself', ps.evaluate("daWoAll().find(o=>o.kind==='transfer').status") == 'done')
    ps.evaluate("addTX({id:'h1',type:'harvesting',date:daToday(),unit:'F3.S04T01',fishNo:100,_skipValidation:true})"); ps.wait_for_timeout(300)
    check('W11 the harvest recorded → the harvest order closes by itself', ps.evaluate("daWoAll().find(o=>o.kind==='harvest').status") == 'done')
    c3, pi = new_page(p, sb); pi.set_viewport_size({'width': 390, 'height': 844}); login(pi, 'irfan@workers.dar-aqua.app', 'work123'); pi.wait_for_function('() => !!window._cloudSyncDone', timeout=10000); pi.wait_for_timeout(600); pi.evaluate('daTabRefresh()'); pi.wait_for_timeout(1200)
    check('W12 Irfan (F1) gets nothing of F3', pi.evaluate("document.getElementById('wo-bell').textContent") == '🔔')
    pe.evaluate("daRealtimePull()"); pe.wait_for_timeout(1500); pe.evaluate("show('entry-status',true)"); pe.wait_for_timeout(400)
    es = pe.inner_text('#es-wo') if pe.query_selector('#es-wo') else ''
    check('W13 the entry status board: routine 1/2 for F3 and the open orders', 'روتين 1/2' in es, es[:200])
    pi.click('#lang-btn'); pi.wait_for_timeout(150); pi.click('#da-langmenu button[data-l="ur"]'); pi.wait_for_timeout(300)
    ps.click('#lang-btn'); ps.wait_for_timeout(150); ps.click('#da-langmenu button[data-l="ur"]'); ps.wait_for_timeout(300); ps.evaluate("show('wo-mine',true)"); ps.wait_for_timeout(300)
    check('W14 in Urdu for the worker', 'آج کا روزانہ کام' in ps.inner_text('#content'))
    check('W15 workers cannot give orders', not ps.evaluate("canAccessView('work-orders')"))
    check('W16 no page errors', not pe._errs and not ps._errs and not pi._errs, pe._errs + ps._errs + pi._errs)
    for c in (c1, c2, c3): c.close()
    fails = [r for r in RESULTS if not r[1]]
    for nm, ok, dt in RESULTS: print(('✅ ' if ok else '❌ ') + nm + ('' if ok else f'  → {str(dt)[:300]}'))
    print(f'\n{len(RESULTS)-len(fails)}/{len(RESULTS)} passed')
